"""Independent literal reading of PROTOCOL.md, written for cross-checking.

Deliberately naive: every repair step re-derives every scenario value from
scratch, agreement bands enumerate all endpoint pairs, and the state machine is
a plain dict.  Slow but directly traceable to the contract text.
"""

import hashlib
from math import gcd


def is_int(x):
    return type(x) is int


class Ref:
    def __init__(self, topo):
        self.nodes = {n["id"]: n for n in topo["nodes"]}
        self.name_of = {i: n["name"] for i, n in self.nodes.items()}
        self.id_of = {n["name"]: i for i, n in self.nodes.items()}
        self.external = [self.id_of[n] for n in topo["external_nodes"]]
        self.extset = set(self.external)
        entries = []
        for link in topo["links"]:
            s, d, c = link["source"], link["target"], link["capacity"]
            for a, b in ((s, d), (d, s)):
                keys = (f"low_{self.name_of[a]}_egress_to_{self.name_of[b]}",
                        f"low_{self.name_of[b]}_ingress_from_{self.name_of[a]}")
                entries.append(((a, b), c, keys, keys))
        for nid in self.external:
            nm = self.name_of[nid]
            c = self.nodes[nid]["external_capacity"]
            entries.append(((-1, nid), c, (f"low_{nm}_origination",),
                            (f"low_{nm}_origination",)))
            entries.append(((nid, -1), c, (f"low_{nm}_termination",),
                            (f"low_{nm}_termination",)))
        entries.sort(key=lambda e: e[0])
        self.flows = [e[0] for e in entries]
        self.cap = {e[0]: e[1] for e in entries}
        self.reports = {e[0]: e[2] for e in entries}
        self.keys = {e[0]: e[3] for e in entries}
        self.keycap = {}
        for pair, c, rep, ky in entries:
            for k in ky:
                self.keycap[k] = c
        self.routers = sorted({n for pair in self.flows for n in pair if n != -1})
        self.incident = {r: [p for p in self.flows if r in p and -1 not in (p[0],) and r in p]
                         for r in self.routers}
        self.incident = {r: [p for p in self.flows if r in p] for r in self.routers}

    # ------------------------------------------------------------ band
    @staticmethod
    def band(entries, epsilon):
        """entries: list of (value, weight). Enumerate every endpoint pair."""
        if not entries:
            return None
        values = sorted({v for v, _ in entries})
        best = None
        for lo in values:
            for hi in values:
                if hi < lo:
                    continue
                if 1000000 * (hi - lo) > epsilon * hi:
                    continue
                mass = 0
                total = 0
                for v, w in entries:
                    if lo <= v <= hi:
                        mass += w
                        total += v * w
                key = (-mass, lo, hi)
                if best is None or key < best[0]:
                    best = (key, total // mass)
        return best[1], -best[0][0]

    # ------------------------------------------------------------ state
    def reset(self, settings):
        self.settings = settings
        self.counters = {}
        self.demands = {}
        self.plan = None
        self.plan_items = None
        self.cache = []          # list of [key, payload] oldest first
        self.snaps = {}

    def W(self, r, t, pair):
        a, b = pair
        text = f"{self.settings['seed']}:{r}:{t}:{a}:{b}"
        return int.from_bytes(hashlib.sha256(text.encode()).digest()[:8], "big")

    def predicted(self):
        loads = {}
        out = {}
        inc = {}
        for (s, d), v in self.demands.items():
            out[s] = out.get(s, 0) + v
            inc[d] = inc.get(d, 0) + v
        for pair in self.flows:
            if pair[0] == -1:
                loads[pair] = out.get(pair[1], 0)
            elif pair[1] == -1:
                loads[pair] = inc.get(pair[0], 0)
        if self.plan is not None:
            acc = {}
            for (s, d, path, weight) in self.plan:
                v = self.demands.get((s, d), 0)
                if not v:
                    continue
                for a, b in zip(path, path[1:]):
                    pair = (a, b)
                    acc[pair] = acc.get(pair, 0) + v * weight
            for pair in self.flows:
                if pair[0] != -1 and pair[1] != -1:
                    loads[pair] = acc.get(pair, 0) // 1000
        else:
            for pair in self.flows:
                if pair[0] != -1 and pair[1] != -1:
                    loads[pair] = None
        return loads

    def key(self):
        counters = tuple(sorted(self.counters.items()))
        demands = tuple(sorted((s, d, v) for (s, d), v in self.demands.items() if v))
        routes = None if self.plan is None else tuple(sorted(self.plan))
        st = self.settings
        return (counters, demands, routes, st["seed"], st["trials"], st["epsilon"])

    def patch(self, event):
        if set(event) != {"op", "demands", "counters"}:
            return False
        dl, cc = event["demands"], event["counters"]
        if type(dl) is not list or type(cc) is not dict:
            return False
        seen = set()
        staged_d = []
        for item in dl:
            if type(item) is not list or len(item) != 3:
                return False
            s, d, v = item
            if not (is_int(s) and is_int(d) and is_int(v)):
                return False
            if s == d or s not in self.extset or d not in self.extset:
                return False
            if (s, d) in seen:
                return False
            seen.add((s, d))
            bound = min(self.nodes[s]["external_capacity"],
                        self.nodes[d]["external_capacity"])
            if v < 0 or v > bound:
                return False
            staged_d.append(((s, d), v))
        staged_c = []
        for k, cell in cc.items():
            if k not in self.keycap:
                return False
            if cell is None:
                staged_c.append((k, None))
                continue
            if type(cell) is not dict or "perturbed" not in cell:
                return False
            if set(cell) - {"perturbed", "ground_truth", "corrected", "confidence"}:
                return False
            p = cell["perturbed"]
            if p is None:
                staged_c.append((k, None))
                continue
            if not is_int(p) or p < 0 or p > self.keycap[k]:
                return False
            staged_c.append((k, p))
        self.demands.update(dict(staged_d))
        for k, v in staged_c:
            if v is None:
                self.counters.pop(k, None)
            else:
                self.counters[k] = v
        return True

    def routes(self, event):
        paths = event["paths"]
        if paths is None:
            self.plan = None
            self.plan_items = None
            return True
        plan = []
        for src_name, per_dest in paths.items():
            s = self.id_of[src_name]
            for dst_name, bundle in per_dest.items():
                d = self.id_of[dst_name]
                for item in bundle:
                    ids = tuple(self.id_of[n] for n in item["path"])
                    plan.append((s, d, ids, item["weight"]))
        self.plan = plan
        return True

    def pool(self, pair, loads, use_prediction):
        pool = []
        for k in self.reports[pair]:
            v = self.counters.get(k)
            if v is not None:
                pool.append(v)
        if use_prediction:
            p = loads[pair]
            pool.append(min(p, self.cap[pair]))
        return pool

    def repair(self, event):
        key = self.key()
        found = None
        for entry in self.cache:
            if entry[0] == key:
                found = entry
                break
        hit = found is not None
        if hit:
            payload = found[1]
            self.cache.remove(found)
            self.cache.append(found)
        else:
            payload = self.compute()
            if self.settings["cache_slots"] > 0:
                self.cache.append([key, payload])
                while len(self.cache) > self.settings["cache_slots"]:
                    self.cache.pop(0)
        self.snaps[event["id"]] = payload
        return payload

    def compute(self):
        st = self.settings
        trials = st["trials"]
        epsilon = st["epsilon"]
        use_prediction = self.plan is not None
        loads = self.predicted()
        pools = {p: self.pool(p, loads, use_prediction) for p in self.flows}
        fixed = {}
        order = []
        conf = {}
        remaining = list(self.flows)
        while remaining:
            scores = {}
            for f in remaining:
                evidence = [(v, trials) for v in pools[f]]
                for r in f:
                    if r == -1:
                        continue
                    rems = []
                    for t in range(trials):
                        values = {}
                        for g in self.incident[r]:
                            pool = pools[g]
                            if g in fixed:
                                values[g] = fixed[g]
                            elif not pool:
                                values[g] = 0
                            else:
                                values[g] = pool[self.W(r, t, g) % len(pool)]
                        if f[1] == r:      # f enters r
                            other = sum(v for g, v in values.items()
                                        if g[1] == r and g != f)
                            whole = sum(v for g, v in values.items() if g[0] == r)
                            rem = whole - other
                        else:              # f leaves r
                            other = sum(v for g, v in values.items()
                                        if g[0] == r and g != f)
                            whole = sum(v for g, v in values.items() if g[1] == r)
                            rem = whole - other
                        rems.append(max(0, min(self.cap[f], rem)))
                    item = self.band([(v, 1) for v in rems], epsilon)
                    evidence.append(item)
                rep, mass = self.b
                scores[f] = self.band(evidence, epsilon)
            best = max(remaining, key=lambda f: (scores[f][1], -f))
            fixed[best] = scores[best][0]
            conf[best] = scores[best][1]
            order.append(best)
            remaining.remove(best)
        links = []
        counters = {}
        for pair in self.flows:
            num, den = conf[pair], trials
            g = gcd(num, den)
            links.append([pair[0], pair[1], fixed[pair], num // g, den // g])
            for k in self.keys[pair]:
                counters[k] = {"corrected": fixed[pair],
                               "confidence": [num // g, den // g]}
        return {"links": links, "order": [[a, b] for a, b in order],
                "counters": counters}

    def validate(self, event):
        payload = self.snaps[event["id"]]
        loads = self.predicted()
        cut = self.settings["cutoff"]
        bias = self.settings["bias"]
        tau = self.settings["tau"]
        checked = passed = 0
        failed = []
        for index, pair in enumerate(self.flows):
            expected = loads[pair]
            if expected is None:
                continue
            record = payload["links"][index]
            cn, cd = record[3], record[4]
            if cn * cut[1] < cut[0] * cd:
                continue
            x = record[2] * 1000000
            y = expected * (1000000 - bias)
            ok = 1000000 * abs(x - y) <= tau * max(x, y)
            for k in self.keys[pair]:
                checked += 1
                if ok:
                    passed += 1
                else:
                    failed.append(k)
        if checked == 0:
            consistent = None
        else:
            gam = self.settings["gamma"]
            consistent = passed * gam[1] >= checked * gam[0]
        return {"checked": checked, "passed": passed,
                "consistent": consistent, "failed": sorted(failed)}

    def replay(self, events, settings):
        self.reset(settings)
        out = []
        for event in events:
            op = event["op"]
            if op == "patch":
                out.append({"op": "patch", "accepted": self.patch(event)})
            elif op == "routes":
                self.routes(event)
                out.append({"op": "routes", "accepted": True})
            elif op == "repair":
                payload = self.repair(event)
                out.append({"op": "repair", "id": event["id"],
                            "cache_hit": self.last_hit,
                            "links": payload["links"], "order": payload["order"],
                            "counters": payload["counters"]})
            else:
                res = self.validate(event)
                out.append({"op": "validate", "id": event["id"], **res})
        return out


def answer(request):
    streams = []
    for stream in request["streams"]:
        ref = Ref(stream["topology"])
        streams.append({"events": ref.replay(stream["events"], stream["settings"])})
    return {"streams": streams}
